INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("ヤマト", 130011, 100, "2030/01/01 14:59:59", 2.1, "2024/10/31 12:00:00", -416.5, "ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか", 3001100, 3001, 0.0, 1, 2);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("ヤマト", 130011, 101, "2030/01/01 14:59:59", 5.68, "2024/10/31 12:00:00", -416.5, "他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか", 3001101, 3001, 0.0, 4, 2);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("ヤマト", 130011, 102, "2030/01/01 14:59:59", 0.0, "2024/10/31 12:00:00", -416.5, "なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。", 3001102, 3001, 0.0, 1, 1);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("フブキ", 130211, 100, "2030/01/01 14:59:59", 0.0, "2024/10/31 12:00:00", -416.5, "え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？", 3002100, 3002, 0.0, 1, 1);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("フブキ", 130211, 101, "2030/01/01 14:59:59", 0.0, "2024/10/31 12:00:00", -416.5, "ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡", 3002101, 3002, 0.0, 1, 1);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("フブキ", 130211, 102, "2030/01/01 14:59:59", 8.53, "2024/10/31 12:00:00", -416.5, "へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ", 3002102, 3002, 0.0, 5, 2);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("フブキ", 130211, 103, "2030/01/01 14:59:59", 5.67, "2024/10/31 12:00:00", -416.5, "なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？", 3002103, 3002, 0.0, 7, 1);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("フブキ", 130211, 104, "2030/01/01 14:59:59", 0.0, "2024/10/31 12:00:00", -416.5, "ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？", 3002104, 3002, 0.0, 1, 1);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("フブキ", 130211, 300, "2030/01/01 14:59:59", 0.0, "2024/10/31 12:00:00", -416.5, "あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？", 3002300, 3004, 0.0, 3, 3);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("フブキ", 130211, 301, "2030/01/01 14:59:59", 0.0, "2024/10/31 12:00:00", -416.5, "ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡", 3002400, 3005, 0.0, 7, 7);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("フブキ", 130211, 200, "2030/01/01 14:59:59", 4.4, "2024/10/31 12:00:00", -416.5, "きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪", 3003200, 3003, 0.0, 2, 1);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("フブキ", 130211, 201, "2030/01/01 14:59:59", 0.0, "2024/10/31 12:00:00", -416.5, "は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ", 3003201, 3003, 0.0, 7, 7);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("フブキ", 130211, 202, "2030/01/01 14:59:59", 5.6, "2024/10/31 12:00:00", -416.5, "お兄さんってば、ぼくがいないと\nほんとザッコザコだよね～\nもっと感謝しろし～♪", 3003202, 3003, 0.0, 1, 2);
